contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: attempt to set owner to newOwner from this contract
    function run(address newOwner) public payable {
        require(true);

        // read owner before
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;

        // make the state-changing call as a top-level statement and capture revert via try/catch
        bool reverted;
        bool returnedTrue;
        bool ok = c.setOwner(newOwner); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
            returnedTrue = false;
        } else {
            reverted = false;
            returnedTrue = ok;
        }

        // read owner after
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;

        // Single general assertion combining the expected relation:
        // - call reverts iff this contract was not the owner before the call
        // - if it did not revert then it must have returned true and ownerAfter == newOwner
        assert(
            (reverted == (address(this) != ownerBefore))
            && (reverted || (returnedTrue && ownerAfter == newOwner))
        );
    }

    receive() external payable {}
}

